#!/bin/bash
# Runs once on the server's first boot (Oracle passes it as user-data).
# Installs the maze-pages website and serves it on port 80.
mkdir -p /srv/maze
echo '' | base64 -d | gunzip > /srv/maze/index.html
cat > /etc/systemd/system/maze.service <<'UNIT'
[Unit]
Description=Maze pages website
After=network.target
[Service]
ExecStart=/usr/bin/python3 -m http.server 80 --directory /srv/maze
Restart=always
[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable --now maze
# Oracle's Ubuntu images block everything except SSH in iptables; open port 80.
iptables -I INPUT 1 -p tcp --dport 80 -j ACCEPT
netfilter-persistent save || true
# Oracle Linux images use firewalld instead.
command -v firewall-cmd >/dev/null && { firewall-cmd --permanent --add-service=http; firewall-cmd --reload; }
